mkdir -p /tmp/bot-test && cat > /tmp/bot-test/test.mjs <<'EOF'
import { reserve } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/baseline-g4-3/bot.mjs';
import { execFileSync, spawn } from 'node:child_process';
import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import assert from 'node:assert/strict';

const H = 3600_000, DAY = 24 * H;
const dir = mkdtempSync(join(tmpdir(), 'state-'));
process.env.STATE_DIR = join(dir, 'nested', 'state'); // missing parents on purpose
const t0 = new Date('2026-10-23T10:00:00Z');
const at = (ms) => new Date(t0.getTime() + ms);

// 1. Mixed channels, 5 allowed, 6th blocked with correct retryAt
const chans = ['sms', 'push', 'chat', 'sms', 'push'];
for (let i = 0; i < 5; i++) {
  const r = await reserve('cust-A', chans[i], at(i * H));
  assert.equal(r.allowed, true); assert.equal(r.retryAt, null);
}
const b = await reserve('cust-A', 'chat', at(10 * H));
assert.equal(b.allowed, false);
assert.equal(b.retryAt.getTime(), t0.getTime() + DAY); // first send (t0) + 24h
console.log('blocked reason:', b.reason);

// 2. Exact boundary: one ms before retryAt blocked, at retryAt allowed
const before = await reserve('cust-A', 'sms', new Date(b.retryAt.getTime() - 1));
assert.equal(before.allowed, false);
assert.equal(before.retryAt.getTime(), b.retryAt.getTime());
const atRetry = await reserve('cust-A', 'sms', b.retryAt);
assert.equal(atRetry.allowed, true);
console.log('allowed reason:', atRetry.reason);

// 3. Different customer unaffected
const other = await reserve('cust-B', 'push', at(10 * H));
assert.equal(other.allowed, true);

// 4. Persistence across processes: a new node process sees the same state
const child = (args) => execFileSync(process.execPath, ['--input-type=module', '-e', `
  import { reserve } from '${new URL('file://<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/baseline-g4-3/bot.mjs').pathname}';
  const r = await reserve(${JSON.stringify(args.u)}, ${JSON.stringify(args.c)}, new Date(${args.t}));
  console.log(JSON.stringify({ allowed: r.allowed, retryAt: r.retryAt }));`],
  { env: process.env, encoding: 'utf8' }).trim();
const fromChild = JSON.parse(child({ u: 'cust-A', c: 'chat', t: at(11 * H).getTime() }));
assert.equal(fromChild.allowed, false);
console.log('child process result:', fromChild);

// 5. Sliding window: after t0 entries age out, new sends allowed; counts remain correct
const later = await reserve('cust-A', 'push', at(DAY + 2 * H));
assert.equal(later.allowed, true);

// 6. Concurrency: 12 processes x 3 attempts for one customer at the same instant
for (let round = 0; round < 3; round++) {
  const user = `race-${round}`;
  const now = new Date(Date.now()).toISOString();
  const procs = Array.from({ length: 12 }, () => new Promise((resolve, reject) => {
    const p = spawn(process.execPath, ['--input-type=module', '-e', `
      import { reserve } from '${new URL('file://<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/baseline-g4-3/bot.mjs').pathname}';
      const out = [];
      for (let i = 0; i < 3; i++) out.push((await reserve(${JSON.stringify(user)}, 'sms', new Date(${JSON.stringify(now)}))).allowed);
      console.log(JSON.stringify(out));`], { env: process.env });
    let s = ''; p.stdout.on('data', d => s += d); p.stderr.on('data', d => s += d);
    p.on('close', code => code === 0 ? resolve(JSON.parse(s.trim().split('\n').pop())) : reject(new Error(s)));
  }));
  const results = (await Promise.all(procs)).flat();
  const allowed = results.filter(x => x).length;
  assert.equal(allowed, 5, `round ${round}: allowed=${allowed}`);
  console.log(`race round ${round}: ${allowed} allowed of ${results.length} attempts`);
}

// 7. Input validation and missing STATE_DIR
await assert.rejects(reserve('', 'sms', new Date()), TypeError);
await assert.rejects(reserve('x', 'email', new Date()), TypeError);
await assert.rejects(reserve('x', 'sms', Date.now()), TypeError);
const saved = process.env.STATE_DIR; delete process.env.STATE_DIR;
await assert.rejects(reserve('x', 'sms', new Date()), /STATE_DIR/);
process.env.STATE_DIR = saved;

console.log('ALL CHECKS PASSED');
EOF
cd /tmp/bot-test && node test.mjs
